// Role requirements (edit this node to search for a different role). Fictional example.
return [{
  json: {
    role_title: 'Senior Quant Researcher',
    specialism: 'Quant Research',
    must_have: ['python', 'statistics', 'time series'],
    nice_to_have: ['c++', 'machine learning'],
    locations: ['Dubai', 'London', 'Remote'],
    min_days_since_contact: 30,
    top_n: 5,
  },
}];

// Dummy candidate database (fictional people). Mix of good matches, stale, recently contacted and do-not-contact cases.
const db = [
  { id: 'D01', name: 'Aisha Rahman', specialism: 'Quant Research', skills: ['python', 'statistics', 'time series', 'c++'], location: 'Dubai', stage: 'Held', last_contacted: '2026-03-10', consent: true, do_not_contact: false },
  { id: 'D02', name: 'Sara Lindqvist', specialism: 'Quant Research', skills: ['python', 'statistics', 'machine learning'], location: 'Stockholm', stage: 'Held', last_contacted: '2026-01-22', consent: true, do_not_contact: false },
  { id: 'D03', name: 'Tom Becker', specialism: 'Trading Tech', skills: ['c++', 'low latency', 'python'], location: 'London', stage: 'Held', last_contacted: '2025-11-05', consent: true, do_not_contact: false },
  { id: 'D04', name: 'Li Wei', specialism: 'Quant Research', skills: ['python', 'time series', 'statistics', 'machine learning'], location: 'Singapore', stage: 'Submitted', last_contacted: '2026-10-12', consent: true, do_not_contact: false },
  { id: 'D05', name: 'Maria Costa', specialism: 'Software Engineering', skills: ['java', 'kubernetes'], location: 'Lisbon', stage: 'Held', last_contacted: '2026-06-30', consent: true, do_not_contact: false },
  { id: 'D06', name: 'Omar Haddad', specialism: 'Quant Research', skills: ['r', 'statistics'], location: 'Dubai', stage: 'Held', last_contacted: '2026-02-14', consent: true, do_not_contact: false },
  { id: 'D07', name: 'Daniel Okafor', specialism: 'Infrastructure', skills: ['linux', 'networking'], location: 'London', stage: 'Placed', last_contacted: '2026-09-01', consent: true, do_not_contact: false },
  { id: 'D08', name: 'Yuki Tanaka', specialism: 'Quant Research', skills: ['python', 'statistics', 'time series', 'c++', 'machine learning'], location: 'Tokyo', stage: 'Held', last_contacted: '2025-05-20', consent: true, do_not_contact: true },
  { id: 'D09', name: 'Hannah Meyer', specialism: 'Quant Research', skills: ['python', 'time series'], location: 'London', stage: 'Held', last_contacted: '2026-04-02', consent: false, do_not_contact: false },
  { id: 'D10', name: 'Rohan Iyer', specialism: 'Quant Research', skills: ['python', 'statistics', 'time series'], location: 'Remote', stage: 'Held', last_contacted: '2025-12-15', consent: true, do_not_contact: false }
];
return db.map((c) => ({ json: c }));

// Rank existing candidates against the role (n8n Code node, "Run once for all items").
// Searches the EXISTING database before any new sourcing. Excludes people who must not be contacted.
// Reads: the "Role requirements" node and the "Candidate database" node.
const role = $('Role requirements').first().json;
const cands = $('Candidate database').all().map((i) => i.json);
const asOf = (typeof ASOF !== 'undefined') ? new Date(ASOF) : new Date();
const days = (d) => (d ? Math.floor((asOf - new Date(d)) / 86400000) : null);

const ranked = [];
const excluded = [];

for (const c of cands) {
  // Hard exclusions first: consent and contact rules beat any score.
  if (c.do_not_contact) { excluded.push({ id: c.id, name: c.name, reason: 'do not contact' }); continue; }
  if (!c.consent) { excluded.push({ id: c.id, name: c.name, reason: 'no consent to be contacted' }); continue; }
  const since = days(c.last_contacted);
  if (since !== null && since < role.min_days_since_contact) {
    excluded.push({ id: c.id, name: c.name, reason: 'contacted ' + since + ' days ago (minimum ' + role.min_days_since_contact + ')' });
    continue;
  }

  const reasons = [];
  let score = 0;
  if (c.specialism === role.specialism) { score += 40; reasons.push('specialism match (+40)'); }

  const hasAll = (list) => list.filter((s) => c.skills.includes(s));
  const must = hasAll(role.must_have);
  const mustPts = Math.round((must.length / role.must_have.length) * 45);
  if (must.length) { score += mustPts; reasons.push(must.length + '/' + role.must_have.length + ' must-have skills: ' + must.join(', ') + ' (+' + mustPts + ')'); }
  const missing = role.must_have.filter((s) => !c.skills.includes(s));
  if (missing.length) reasons.push('missing: ' + missing.join(', '));

  const nice = hasAll(role.nice_to_have);
  const nicePts = Math.min(10, nice.length * 5);
  if (nice.length) { score += nicePts; reasons.push('nice-to-have: ' + nice.join(', ') + ' (+' + nicePts + ')'); }

  if (role.locations.includes(c.location)) { score += 5; reasons.push('location fits: ' + c.location + ' (+5)'); }
  else reasons.push('location outside target: ' + c.location);

  ranked.push({ id: c.id, name: c.name, specialism: c.specialism, location: c.location, stage: c.stage, days_since_contact: since, score, reasons });
}

ranked.sort((a, b) => b.score - a.score || a.id.localeCompare(b.id));
const shortlist = ranked.filter((r) => r.score >= 40).slice(0, role.top_n);

return [{
  json: {
    role: role.role_title,
    searched: cands.length,
    shortlisted: shortlist.length,
    excluded_count: excluded.length,
    shortlist,
    not_shortlisted: ranked.filter((r) => !shortlist.includes(r)).map((r) => ({ id: r.id, name: r.name, score: r.score })),
    excluded,
    human_review_note: 'Shortlist is a proposal. A recruiter must review before anyone is contacted.',
  },
}];

